def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same `_metadata_bounds` the writer uses to locate the block, so a
    stray or unfinished example quoted elsewhere in the body — before or after
    the real block — cannot be mistaken for it. A body with no complete,
    well-formed pair has no metadata as far as this function is concerned.
    """
    if not body or METADATA_BEGIN not in body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
